WITH scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY city, country ORDER BY rating DESC, id) AS row_seq, ROW_NUMBER() OVER (ORDER BY rating, id) AS seq_no, NTILE(10) OVER w_running AS rating_bucket FROM suppliers WINDOW w_running AS (PARTITION BY city ORDER BY rating, id)) SELECT CASE WHEN rating_bucket >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS rating_bucket_tier, SUM(CASE WHEN city = 'Chiang Mai' THEN row_seq ELSE 0 END) AS chiang_mai_row_seq, ROUND(AVG(rating_bucket), 2) AS avg_rating_bucket, SUM(CASE WHEN city = 'Tokyo' THEN seq_no ELSE 0 END) AS tokyo_seq_no FROM scored GROUP BY rating_bucket_tier ORDER BY chiang_mai_row_seq DESC
